#!/usr/bin/env python3
"""One-off (builder container): regenerate why3 run shim from spec, robust version."""
import re

spec = open("/src/portable/builders/tools/why3.sh", encoding="utf-8").read()
m = re.search(r"ft::make_shim '(.*?)'\n", spec, re.S)
shim_body = m.group(1)
shim = (
    "#!/bin/sh\n"
    "# generated by formal-tools portable builders - do not edit\n"
    'FT_ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)\n'
    'TOOL_DIR="$FT_ROOT/tools/why3"\n'
    + shim_body
    + "\n"
)
open("/out/tools/why3/run", "w", encoding="utf-8", newline="\n").write(shim)
print("SHIM_OK bytes=", len(shim))
